feed:
{{- $self := .OutputFormats.Get "Atom" -}}
{{- $html := .OutputFormats.Get "HTML" -}}
{{ .Title | htmlEscape }}
{{ with $html }}{{ .Permalink }}{{ else }}{{ .Permalink }}{{ end }}
{{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}
{{- with $self }}

{{- end }}
{{- with $html }}

{{- end }}
{{- if .Description }}
{{ .Description | plainify | htmlEscape }}
{{- else if .Site.Params.description }}
{{ .Site.Params.description | plainify | htmlEscape }}
{{- end }}
Hugo

  {{ .Title | htmlEscape }}

  {{ .Permalink }}
  {{ .Lastmod.Format "2006-01-02T15:04:05Z07:00" }}
  {{- with .Date }}
  {{ .Format "2006-01-02T15:04:05Z07:00" }}
  {{- end }}

    {{ with .Params.author }}{{ . | htmlEscape }}{{ else }}{{ $.Site.Title | htmlEscape }}{{ end }}

  {{- with .Params.description }}
  {{ . | plainify | htmlEscape }}
  {{- else }}{{ with .Summary }}
  {{ . | plainify | htmlEscape }}
  {{- end }}{{ end }}
  {{- $img := .Params.img | default .Params.image }}
  {{- if $img }}
    {{- $imgURL := $img | relURL }}
    {{- if not (hasPrefix $imgURL "http") }}
      {{- $imgURL = printf "%s%s" $.Site.BaseURL (strings.TrimPrefix "/" $imgURL) }}
    {{- end }}
    {{- /* Detect image type from extension */}}
    {{- $imgType := "image/jpeg" }}
    {{- if strings.HasSuffix $img ".png" }}
      {{- $imgType = "image/png" }}
    {{- else if strings.HasSuffix $img ".webp" }}
      {{- $imgType = "image/webp" }}
    {{- else if strings.HasSuffix $img ".gif" }}
      {{- $imgType = "image/gif" }}
    {{- end }}

  {{- end }}
  {{ .Content | safeHTML }}
